71	@RestController
72	@CrossOrigin(exposedHeaders = "errors, content-type")
73	@RequestMapping("/api")
74	public class OwnerRestControllerV1 implements OwnersApi {
75	
76	    /**
77	     * Syntactic email check: a non-empty local part, a single {@code @}, and a domain that
78	     * contains at least one dot, with no whitespace anywhere. Deliberately lenient — it accepts
79	     * ordinary addresses while rejecting clearly malformed ones such as {@code not-an-email}.
80	     */
81	    private static final Pattern EMAIL_PATTERN =
82	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
83	
84	    /**
85	     * Disposable email domains that are refused on create. An email whose domain (the part after the
86	     * {@code @}, compared case-insensitively) is in this set is rejected with a 400, since such
87	     * addresses are throwaway and unsuitable for contacting an owner.
88	     */
89	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
90	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
91	
92	    /**
93	     * Dedicated audit logger. On a successful create an audit line carrying the owner id, the
94	     * customerCode, the registrationDate and the membershipLevel is emitted through this logger.
95	     */
96	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
97	
98	    private final ClinicService clinicService;
99	
100	    private final OwnerMapper ownerMapper;
101	
102	    private final PetMapper petMapper;
103	
104	    private final VisitMapper visitMapper;
105	
106	    public OwnerRestControllerV1(ClinicService clinicService,
107	                                 OwnerMapper ownerMapper,
108	                                 PetMapper petMapper,
109	                                 VisitMapper visitMapper) {
110	        this.clinicService = clinicService;
111	        this.ownerMapper = ownerMapper;
112	        this.petMapper = petMapper;
113	        this.visitMapper = visitMapper;
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
119	        Collection<Owner> owners;
120	        if (lastName != null) {
121	            owners = this.clinicService.findOwnerByLastName(lastName);
122	        } else {
123	            owners = this.clinicService.findAllOwners();
124	        }
125	        if (owners.isEmpty()) {
126	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
127	        }
128	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
129	    }
130	
131	    /**
132	     * Rejects an owner payload that is missing or blank in any required field, listing the name of
133	     * each offending field so the caller receives a 400 with a populated {@code errors} array.
134	     */
135	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
136	        List<String> missing = new ArrayList<>();
137	        if (isBlank(ownerFieldsDto.getFirstName())) {
138	            missing.add("firstName");
139	        }
140	        if (isBlank(ownerFieldsDto.getLastName())) {
141	            missing.add("lastName");
142	        }
143	        if (isBlank(ownerFieldsDto.getAddress())) {
144	            missing.add("address");
145	        }
146	        if (isBlank(ownerFieldsDto.getCity())) {
147	            missing.add("city");
148	        }
149	        if (isBlank(ownerFieldsDto.getTelephone())) {
150	            missing.add("telephone");
151	        }
152	        if (!missing.isEmpty()) {
153	            throw new RequiredFieldsMissingException(missing);
154	        }
155	    }
156	
157	    private static boolean isBlank(String value) {
158	        return value == null || value.isBlank();
159	    }
160	
161	    /**
162	     * Normalizes an address on create: leading/trailing whitespace is trimmed, every run of internal
163	     * whitespace is collapsed to a single space, the value is upper-cased and common abbreviations are
164	     * expanded token-by-token ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The
165	     * normalized value is what gets stored, returned and used for every address comparison; a value
166	     * that is blank (or {@code null}) normalizes to the empty string so the required-field check
167	     * rejects it.
168	     *
169	     * @param address the raw address as supplied by the caller, may be {@code null}
170	     * @return the normalized address ({@code ""} when blank or {@code null})
171	     */
172	    private static String normalizeAddress(String address) {
173	        if (address == null) {
174	            return "";
175	        }
176	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
177	        if (collapsed.isEmpty()) {
178	            return "";
179	        }
180	        String[] tokens = collapsed.split(" ");
181	        StringBuilder sb = new StringBuilder(collapsed.length());
182	        for (int i = 0; i < tokens.length; i++) {
183	            String token = tokens[i];
184	            switch (token) {
185	                case "ST" -> token = "STREET";
186	                case "RD" -> token = "ROAD";
187	                case "AVE" -> token = "AVENUE";
188	                default -> { }
189	            }
190	            if (i > 0) {
191	                sb.append(' ');
192	            }
193	            sb.append(token);
194	        }
195	        return sb.toString();
196	    }
197	
198	    /**
199	     * Normalizes a telephone on create into E.164 form. Spaces, dashes and brackets are stripped.
200	     * A leading {@code +} and its country code are kept as given; otherwise the country code
201	     * {@code +61} is assumed and a single leading {@code 0} is dropped from the national digits.
202	     * The result must carry 8 to 15 digits after the {@code +}. In addition, when the country code
203	     * is recognized the national number must have the exact length that code requires ({@code +61}
204	     * expects 9 national digits, {@code +1} expects 10). Returns the E.164 string to be stored and
205	     * returned.
206	     *
207	     * @param telephone the raw telephone as supplied by the caller
208	     * @return the normalized E.164 telephone (a {@code +} followed by 8 to 15 digits)
209	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number, or its
210	     *     national-number length is wrong for its country code
211	     */
212	    private static String normalizeTelephone(String telephone) {
213	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
214	        String e164;
215	        if (cleaned.startsWith("+")) {
216	            e164 = "+" + cleaned.substring(1);
217	        } else {
218	            String national = cleaned;
219	            if (national.startsWith("0")) {
220	                national = national.substring(1);
221	            }
222	            e164 = "+61" + national;
223	        }
224	        String digits = e164.substring(1);
225	        if (!digits.matches("\\d{8,15}")) {
226	            throw new InvalidTelephoneException(
227	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
228	        }
229	        if (digits.startsWith("61")) {
230	            requireNationalLength(digits.substring(2), 9, "+61");
231	        } else if (digits.startsWith("1")) {
232	            requireNationalLength(digits.substring(1), 10, "+1");
233	        }
234	        return e164;
235	    }
236	
237	    /**
238	     * Enforces that the national portion of an E.164 number has the exact number of digits its
239	     * country code requires.
240	     *
241	     * @param national the national-number digits (the part after the country code)
242	     * @param expected the exact national-number length the country code requires
243	     * @param countryCode the country code, for the error message
244	     * @throws InvalidTelephoneException if {@code national} does not have exactly {@code expected} digits
245	     */
246	    private static void requireNationalLength(String national, int expected, String countryCode) {
247	        if (national.length() != expected) {
248	            throw new InvalidTelephoneException(
249	                "Telephone with country code '" + countryCode + "' must have " + expected
250	                    + " national digits");
251	        }
252	    }
253	
254	    /**
255	     * Normalizes an optional email. An absent or blank email is left unset (returns {@code null});
256	     * a present value must be a syntactically valid address and is stored and returned lower-cased.
257	     *
258	     * @param email the raw email as supplied by the caller, may be {@code null}
259	     * @return the lower-cased email, or {@code null} when none was supplied
260	     * @throws InvalidEmailException if a value is present but is not a syntactically valid address
261	     */
262	    private static String normalizeEmail(String email) {
263	        if (email == null || email.isBlank()) {
264	            return null;
265	        }
266	        String trimmed = email.trim();
267	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
268	            throw new InvalidEmailException("Email must be a syntactically valid address");
269	        }
270	        String lowerCased = trimmed.toLowerCase(Locale.ROOT);
271	        String domain = lowerCased.substring(lowerCased.indexOf('@') + 1);
272	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
273	            throw new InvalidEmailException("Email domain is not allowed");
274	        }
275	        return lowerCased;
276	    }
277	
278	    /**
279	     * Derives the single duplicate-detection key that consolidates the former separate telephone,
280	     * email and household checks. The key is {@code normalizedTelephone + '|' + email + '|' +
281	     * householdId}, where the email segment is the empty string when the owner has no email. Because
282	     * the telephone is part of the key, two owners that differ in any one segment (for example two
283	     * members of the same household with different telephones) produce different keys.
284	     *
285	     * @param normalizedTelephone the E.164 telephone of the owner
286	     * @param email the lower-cased email of the owner, may be {@code null}
287	     * @param householdId the stable household identifier of the owner, may be {@code null}
288	     * @return the derived identity key
289	     */
290	    private static String deriveIdentityKey(String normalizedTelephone, String email, String householdId) {
291	        return (normalizedTelephone == null ? "" : normalizedTelephone)
292	            + "|" + (email == null ? "" : email)
293	            + "|" + (householdId == null ? "" : householdId);
294	    }
295	
296	    /**
297	     * Rejects a create only when the new owner's whole {@code identityKey} equals that of an existing
298	     * owner. This one check replaces the former separate telephone, email and household duplicate
299	     * checks: only an exact full-key match is a duplicate, so two owners that differ in any single
300	     * segment are both allowed. Each existing owner's key is derived from its stored, already
301	     * normalized telephone, email and household identifier.
302	     *
303	     * @param identityKey the derived identity key of the owner being created
304	     * @throws DuplicateIdentityException if another owner already has this identity key
305	     */
306	    private void rejectDuplicateIdentity(String identityKey) {
307	        boolean inUse = this.clinicService.findAllOwners().stream()
308	            .anyMatch(existing -> identityKey.equals(
309	                deriveIdentityKey(existing.getTelephone(), existing.getEmail(), existing.getHouseholdId())));
310	        if (inUse) {
311	            throw new DuplicateIdentityException(
312	                "An owner with the same identity key already exists");
313	        }
314	    }
315	
316	    /**
317	     * Rejects a create when an existing owner already belongs to the same household (i.e. carries the
318	     * same computed {@code householdId}, derived from last name and postcode), unless the request
319	     * knowingly opts in via {@code sharesHousehold}. Setting {@code sharesHousehold} bypasses this
320	     * block so the owner is created as a declared member of the existing household; without it, a
321	     * second owner in the same household is a conflict.
322	     *
323	     * @param householdId the computed household identifier of the owner being created
324	     * @param sharesHousehold whether the request opted in to sharing an existing household
325	     * @throws DuplicateHouseholdException if the household already exists and the request did not opt in
326	     */
327	    private void rejectDuplicateHousehold(String householdId, boolean sharesHousehold) {
328	        if (sharesHousehold) {
329	            return;
330	        }
331	        boolean exists = this.clinicService.findAllOwners().stream()
332	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
333	        if (exists) {
334	            throw new DuplicateHouseholdException(
335	                "An owner with the same last name and postcode already exists");
336	        }
337	    }
338	
339	    /**
340	     * Finds a soft-match "possible duplicate" for the owner being created: an existing owner that is
341	     * not a hard identity duplicate but shares this owner's last name (compared case-insensitively) and
342	     * postcode while carrying a different telephone. When the postcode is absent no owner can share it,
343	     * so there is never a match. When several existing owners qualify the one with the lowest id is
344	     * returned, so the result is deterministic.
345	     *
346	     * @param lastName the last name of the owner being created
347	     * @param postcode the postcode of the owner being created, may be {@code null}
348	     * @param normalizedTelephone the E.164 telephone of the owner being created
349	     * @return the id of the matching existing owner, or {@code null} when there is no soft match
350	     */
351	    private Integer findPossibleDuplicateOf(String lastName, String postcode, String normalizedTelephone) {
352	        if (postcode == null || postcode.isBlank()) {
353	            return null;
354	        }
355	        String normalizedLastName = normalizeName(lastName);
356	        return this.clinicService.findAllOwners().stream()
357	            .filter(existing -> normalizedLastName.equals(normalizeName(existing.getLastName())))
358	            .filter(existing -> postcode.equals(existing.getPostcode()))
359	            .filter(existing -> !normalizedTelephone.equals(existing.getTelephone()))
360	            .map(Owner::getId)
361	            .filter(java.util.Objects::nonNull)
362	            .min(Integer::compareTo)
363	            .orElse(null);
364	    }
365	
366	    /**
367	     * Derives the stable household identifier for an owner from its last name and postcode. The value
368	     * is the first twelve hex characters of the SHA-256 of {@code normalizedLastName + '|' + postcode}
369	     * (the last name normalized case-insensitively with surrounding whitespace trimmed; an absent
370	     * postcode contributes the empty string). Because it is a pure function of those two fields, every
371	     * owner with the same last name and postcode is assigned the same identifier automatically, without
372	     * any existing record having to be updated.
373	     *
374	     * @param lastName the last name of the owner being created
375	     * @param postcode the postcode of the owner being created, may be {@code null}
376	     * @return the stable household identifier
377	     */
378	    private static String householdId(String lastName, String postcode) {
379	        String key = normalizeName(lastName) + "|" + (postcode == null ? "" : postcode);
380	        return sha256HexPrefix(key, 12);
381	    }
382	
383	    /**
384	     * The maximum number of owners a single city may contain. A create whose city already holds this
385	     * many owners is rejected, so a city never grows beyond this capacity.
386	     */
387	    private static final int CITY_CAPACITY = 50;
388	
389	    /**
390	     * Rejects a create whose city already contains {@link #CITY_CAPACITY} or more owners, so no city
391	     * ever exceeds its capacity. Cities are compared case-insensitively with surrounding whitespace
392	     * trimmed. The count reflects the
393	     * state before the new owner is persisted, so it excludes the owner being created.
394	     *
395	     * @param city the city of the owner being created
396	     * @throws CityAtCapacityException if the city already contains {@link #CITY_CAPACITY} owners
397	     */
398	    private void rejectCityAtCapacity(String city) {
399	        String normalizedCity = normalizeName(city);
400	        long ownersInCity = this.clinicService.findAllOwners().stream()
401	            .filter(existing -> normalizedCity.equals(normalizeName(existing.getCity())))
402	            .count();
403	        if (ownersInCity >= CITY_CAPACITY) {
404	            throw new CityAtCapacityException(
405	                "The city already contains the maximum number of owners");
406	        }
407	    }
408	
409	    /**
410	     * The maximum number of owners that may be created on a single day. A create made once this many
411	     * owners already carry today's {@code registrationDate} is rejected, so no more than this many
412	     * owners are registered per day.
413	     */
414	    private static final int DAILY_OWNER_LIMIT = 100;
415	
416	    /**
417	     * Rejects a create once {@link #DAILY_OWNER_LIMIT} or more owners have already been created for
418	     * the given business day, counted by {@code registrationDate} equal to the effective (weekend
419	     * rolled forward) registration date of the owner being created. The count reflects the state
420	     * before the new owner is persisted, so it excludes the owner being created.
421	     *
422	     * @param registrationDate the effective business-day registration date of the owner being created
423	     * @throws DailyOwnerLimitExceededException if the day already holds {@link #DAILY_OWNER_LIMIT} owners
424	     */
425	    private void rejectDailyOwnerLimit(LocalDate registrationDate) {
426	        long ownersToday = this.clinicService.findAllOwners().stream()
427	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
428	            .count();
429	        if (ownersToday >= DAILY_OWNER_LIMIT) {
430	            throw new DailyOwnerLimitExceededException(
431	                "The maximum number of owners for today has already been reached");
432	        }
433	    }
434	
435	    /**
436	     * The number of owners that may already exist for a business day before a create is flagged with
437	     * a bulk-signup warning. Once more than this many owners already carry the effective registration
438	     * date, the created owner's {@code bulkSignupWarning} is set to {@code true}.
439	     */
440	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
441	
442	    /**
443	     * Determines whether a create should be flagged with a bulk-signup warning, i.e. whether more than
444	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created for the given business day,
445	     * counted by {@code registrationDate} equal to the effective (weekend rolled forward) registration
446	     * date of the owner being created. The count reflects the state before the new owner is persisted,
447	     * so it excludes the owner being created.
448	     *
449	     * @param registrationDate the effective business-day registration date of the owner being created
450	     * @return {@code true} when more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry the date
451	     */
452	    private boolean bulkSignupWarning(LocalDate registrationDate) {
453	        long ownersToday = this.clinicService.findAllOwners().stream()
454	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
455	            .count();
456	        return ownersToday > BULK_SIGNUP_WARNING_THRESHOLD;
457	    }
458	
459	    /**
460	     * Rolls a registration date forward to a business day: a Saturday or Sunday is advanced to the
461	     * following Monday, any weekday is returned unchanged.
462	     *
463	     * @param date the effective registration date, supplied or defaulted to the server date
464	     * @return the same date when it is a weekday, otherwise the next Monday
465	     */
466	    private static LocalDate toBusinessDay(LocalDate date) {
467	        DayOfWeek dayOfWeek = date.getDayOfWeek();
468	        if (dayOfWeek == DayOfWeek.SATURDAY) {
469	            return date.plusDays(2);
470	        }
471	        if (dayOfWeek == DayOfWeek.SUNDAY) {
472	            return date.plusDays(1);
473	        }
474	        return date;
475	    }
476	
477	    /**
478	     * Builds the customer code assigned to an owner on create, formatted {@code '<REGION>-<HASH8>'}
479	     * where {@code REGION} is the region code derived from the owner's postcode (the region whose
480	     * inclusive range contains the postcode, or {@code 'UNKNOWN'} when the postcode is absent or in
481	     * no known range) and {@code HASH8} is the first eight upper-cased hex characters of the SHA-256
482	     * of {@code normalizedTelephone + lastName}, e.g. {@code 'NSW-1A2B3C4D'}. There is no sequence
483	     * component: the identity is a pure region-and-hash value.
484	     *
485	     * @param postcode the postcode of the owner being created, may be {@code null}
486	     * @param normalizedTelephone the E.164 telephone of the owner being created
487	     * @param lastName the last name of the owner being created
488	     * @return the formatted customer code
489	     */
490	    private String customerCode(String postcode, String normalizedTelephone, String lastName) {
491	        return regionFromPostcode(postcode) + "-" + sha256HexPrefix(normalizedTelephone + lastName, 8);
492	    }
493	
494	    /**
495	     * Returns the region code whose inclusive postcode range contains the given 4-digit postcode
496	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), or {@code 'UNKNOWN'} when the postcode is
497	     * {@code null}, non-numeric, or in no known range.
498	     *
499	     * @param postcode the postcode, may be {@code null}
500	     * @return the region code, or {@code 'UNKNOWN'}
501	     */
502	    private static String regionFromPostcode(String postcode) {
503	        if (postcode == null || postcode.isBlank()) {
504	            return "UNKNOWN";
505	        }
506	        int code;
507	        try {
508	            code = Integer.parseInt(postcode.trim());
509	        } catch (NumberFormatException e) {
510	            return "UNKNOWN";
511	        }
512	        for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
513	            int[] range = entry.getValue();
514	            if (code >= range[0] && code <= range[1]) {
515	                return entry.getKey();
516	            }
517	        }
518	        return "UNKNOWN";
519	    }
520	
521	    /**
522	     * Computes the SHA-256 of {@code value} and returns its first {@code length} hex characters,
523	     * upper-cased.
524	     *
525	     * @param value the string to hash
526	     * @param length the number of leading hex characters to return
527	     * @return the upper-cased hex prefix of the digest
528	     */
529	    private static String sha256HexPrefix(String value, int length) {
530	        try {
531	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
532	            StringBuilder sb = new StringBuilder(digest.length * 2);
533	            for (byte b : digest) {
534	                sb.append(String.format("%02x", b));
535	            }
536	            return sb.substring(0, length).toUpperCase(Locale.ROOT);
537	        } catch (NoSuchAlgorithmException e) {
538	            throw new IllegalStateException("SHA-256 not available", e);
