34	
35	    /**
36	     * Derives the owner's {@code ageBand} from its birthDate relative to the registrationDate:
37	     * {@code MINOR} when under 18, {@code ADULT} when 18 to 64, and {@code SENIOR} when 65 or older.
38	     * Returns {@code null} when the owner has no birthDate or no registrationDate.
39	     */
40	    default OwnerDto.@Nullable AgeBandEnum ageBand(@Nullable Owner owner) {
41	        if (owner == null || owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
42	            return null;
43	        }
44	        int age = java.time.Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
45	        if (age < 18) {
46	            return OwnerDto.AgeBandEnum.MINOR;
47	        }
48	        if (age < 65) {
49	            return OwnerDto.AgeBandEnum.ADULT;
50	        }
51	        return OwnerDto.AgeBandEnum.SENIOR;
52	    }
53	
54	    /**
55	     * Derives the owner's duplicate-detection {@code identityKey}, formatted as
56	     * {@code normalizedTelephone + '|' + email + '|' + householdId} with an empty email segment when
57	     * the owner has no email. This is the same key the create endpoint uses to reject an owner whose
58	     * whole key equals an existing owner's.
59	     */
60	    default @Nullable String identityKey(@Nullable Owner owner) {
61	        if (owner == null) {
62	            return null;
63	        }
64	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
65	        String email = owner.getEmail() == null ? "" : owner.getEmail();
66	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
67	        return telephone + "|" + email + "|" + householdId;
68	    }
69	
70	    /**
71	     * Derives the owner's preferred contact channel: {@code EMAIL} when an email is present,
72	     * otherwise {@code PHONE}.
73	     */
74	    default OwnerDto.@Nullable ContactPreferenceEnum contactPreference(@Nullable Owner owner) {
75	        if (owner == null) {
76	            return null;
77	        }
78	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
79	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
80	    }
81	
82	    /**
83	     * Derives the owner's locality from its region-and-hash identity: the {@code REGION} prefix of
84	     * the {@code customerCode} ({@code '<REGION>-<HASH8>'}), which is the region code derived from
85	     * the postcode on create. Returns the canonical region string, or {@code 'UNKNOWN'} when the
86	     * owner has no customerCode.
87	     */
88	    default @Nullable String locality(@Nullable Owner owner) {
89	        if (owner == null) {
90	            return null;
91	        }
92	        String customerCode = owner.getCustomerCode();
93	        if (customerCode == null) {
94	            return "UNKNOWN";
95	        }
96	        int dash = customerCode.indexOf('-');
97	        return dash < 0 ? "UNKNOWN" : customerCode.substring(0, dash);
98	    }
99	
100	    /**
101	     * Returns the owner's membership points. Starting at 0, it adds 2 when an email is present, 1
102	     * when namesakeCount is 0, 2 when the owner belongs to a household of at least 3 members, and 3
103	     * when tenure exceeds 365 days since the registrationDate. Because a newly created owner has zero
104	     * tenure it never earns the tenure points.
105	     */
106	    default @Nullable Integer membershipPoints(@Nullable Owner owner) {
107	        if (owner == null) {
108	            return null;
109	        }
110	        int points = 0;
111	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
112	        if (hasEmail) {
113	            points += 2;
114	        }
115	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
116	        if (noNamesakes) {
117	            points += 1;
118	        }
119	        boolean largeHousehold = owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3;
120	        if (largeHousehold) {
121	            points += 2;
122	        }
123	        if (hasQualifyingTenure(owner)) {
124	            points += 3;
125	        }
126	        return points;
127	    }
128	
129	    /**
130	     * Returns the owner's numeric membership level from 1 to 4, derived from membershipPoints:
131	     * level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more points.
132	     */
133	    default @Nullable Integer membershipLevel(@Nullable Owner owner) {
134	        Integer points = membershipPoints(owner);
135	        if (points == null) {
136	            return null;
137	        }
138	        if (points <= 1) {
139	            return 1;
140	        }
141	        if (points <= 3) {
142	            return 2;
143	        }
144	        if (points <= 5) {
145	            return 3;
146	        }
147	        return 4;
148	    }
149	
150	    /**
151	     * Whether the owner's tenure exceeds 365 days, i.e. more than a year has elapsed between its
152	     * registrationDate and the current date. Returns {@code false} when the registrationDate is
153	     * absent (or in the future), so a newly created owner has no qualifying tenure.
154	     */
155	    default boolean hasQualifyingTenure(@Nullable Owner owner) {
156	        if (owner == null || owner.getRegistrationDate() == null) {
157	            return false;
158	        }
159	        long tenureDays = java.time.temporal.ChronoUnit.DAYS.between(
160	            owner.getRegistrationDate(), java.time.LocalDate.now());
161	        return tenureDays > 365;
162	    }
163	
164	    /**
165	     * Formats an owner's membership number as {@code '<customerCode>-M<YY>'}, where YY is the
166	     * last two digits of the registrationDate year, e.g. {@code 'MEL-SMI-0007-M26'}.
167	     */
168	    default @Nullable String membershipNumber(@Nullable Owner owner) {
169	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
170	            return null;
171	        }
172	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
173	    }
174	
175	    /**
176	     * Returns the Luhn check digit (0-9) computed over the digits contained in the owner's
177	     * customerCode, or {@code null} when the owner or its customerCode is absent.
178	     */
179	    default @Nullable Integer checkDigit(@Nullable Owner owner) {
180	        if (owner == null || owner.getCustomerCode() == null) {
181	            return null;
182	        }
183	        String s = owner.getCustomerCode();
184	        int sum = 0;
185	        boolean dbl = true;
186	        for (int i = s.length() - 1; i >= 0; i--) {
187	            char c = s.charAt(i);
188	            if (c < '0' || c > '9') {
189	                continue;
190	            }
191	            int d = c - '0';
192	            if (dbl) {
193	                d *= 2;
194	                if (d > 9) {
195	                    d -= 9;
196	                }
197	            }
198	            sum += d;
199	            dbl = !dbl;
200	        }
201	        return (10 - (sum % 10)) % 10;
202	    }
203	
204	    /**
205	     * Formats the owner's stored E.164 {@code telephone} for humans: the country code, a space, then
206	     * the national digits grouped in threes separated by spaces, e.g. {@code '+61 412 345 678'} for a
207	     * stored {@code '+61412345678'}. The country code is the single digit for the {@code +1} and
208	     * {@code +7} plans and two digits otherwise. Returns the raw value unchanged when it is not a
209	     * {@code '+'}-prefixed digit string, or {@code null} when absent.
210	     */
211	    default @Nullable String telephoneDisplay(@Nullable Owner owner) {
212	        if (owner == null) {
213	            return null;
214	        }
215	        String telephone = owner.getTelephone();
216	        if (telephone == null || !telephone.matches("\\+\\d+")) {
217	            return telephone;
218	        }
219	        String digits = telephone.substring(1);
220	        int countryCodeLength = (digits.startsWith("1") || digits.startsWith("7")) ? 1 : 2;
221	        countryCodeLength = Math.min(countryCodeLength, digits.length());
222	        String countryCode = digits.substring(0, countryCodeLength);
223	        String national = digits.substring(countryCodeLength);
224	        StringBuilder sb = new StringBuilder("+").append(countryCode);
225	        for (int i = 0; i < national.length(); i += 3) {
226	            sb.append(' ').append(national, i, Math.min(i + 3, national.length()));
227	        }
228	        return sb.toString();
229	    }
230	
231	    /**
232	     * Formats an owner's stored names as {@code 'LastName, FirstName'}.
233	     */
234	    default @Nullable String displayName(@Nullable Owner owner) {
235	        if (owner == null) {
236	            return null;
237	        }
238	        return owner.getLastName() + ", " + owner.getFirstName();
239	    }
240	
241	    /**
242	     * Formats an owner's initials as the upper-cased first letters of firstName and
243	     * lastName, dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
244	     */
245	    default @Nullable String initials(@Nullable Owner owner) {
246	        if (owner == null) {
