248	        }
249	        StringBuilder sb = new StringBuilder();
250	        String firstName = owner.getFirstName();
251	        if (firstName != null && !firstName.isEmpty()) {
252	            sb.append(Character.toUpperCase(firstName.charAt(0))).append('.');
253	        }
254	        String lastName = owner.getLastName();
255	        if (lastName != null && !lastName.isEmpty()) {
256	            sb.append(Character.toUpperCase(lastName.charAt(0))).append('.');
257	        }
258	        return sb.toString();
259	    }
